const clamp = (n,min,max) => Math.min(max,Math.max(min,n));
const randomInt = (min,max,rng=Math.random) => min + Math.floor(rng() * (max-min+1));
export const quarterLabel = n => `${2028+Math.floor(n/4)} Q${n%4+1}`;
export const money = n => `${n < 0 ? '−' : ''}$${(Math.abs(n)/1_000_000).toFixed(1)}m`;
export const preciseMoney = n => n>=1_000_000?money(n):`$${Math.round(n/1_000).toLocaleString()}k`;
export const exactKey = (genre,themes) => `${genre}|${[...themes].sort().join('+')}`;

export function compatibility(genre, themes) {
  if (themes.length === 2 && genre === '處境劇' && themes.includes('恐怖') && themes.includes('愛情')) return 'x';
  const tiers = themes.map(theme => synergy[genre]?.[theme] ?? 'o');
  if (tiers.includes('x')) return 'x';
  return tiers.includes('double-o') ? 'double-o' : 'o';
}

export function catalogForQuarter(quarter) {
  const m = quarter % 12;
  const rotation=ACQUISITION_GROUPS.flatMap(group=>{
    const offers=[],used=new Set();
    const add=(n,id)=>{
      const [title,subcategory,cost,quality,rating,buzz,packageEpisodes,poolOrigin]=group.pool[n];
      // Package lengths are game rules, not claims about the original release.
      const episodes=packageEpisodes??{film:1,series:20,variety:12,documentary:6,information:12,politics:12,korean:16,japanese:10,taiwan:12,western:10,chinese:30}[group.id]??12;
      const origin=poolOrigin??group.origin??'香港';
      const network=group.id==='series'?(title.startsWith('瑪嘉烈與大衛')?'ViuTV':'TVB'):
        group.id==='korean'?'外購韓劇':
        group.id==='japanese'?'外購日劇':
        group.id==='taiwan'?'外購台劇':
        group.id==='western'?'外購歐美劇':
        group.id==='chinese'?'外購內地劇':
        group.id==='variety'?(['全民造星','全民造星IV','囝囝女女730'].includes(title)?'ViuTV':'TVB'):
        group.id==='information'&&['東張西望','南美潮什麼 2'].includes(title)?'TVB':'其他';
      offers.push({id,title,category:group.label,subcategory,group:group.id,cost,quality,rating,buzz,episodes,network,origin});
      used.add(n);
    };

    // Determine the month 0 indices for this group:
    const month0Indices = [];
    if (group.legacyCount > 0) {
      for (let i = 0; i < group.legacyCount; i++) {
        month0Indices.push((i * 5) % group.legacyPoolLength);
      }
      let n = group.legacyPoolLength;
      while (month0Indices.length < group.count) {
        const idx = n % group.pool.length;
        if (!month0Indices.includes(idx)) month0Indices.push(idx);
        n++;
      }
    } else {
      for (let i = 0; i < group.count; i++) month0Indices.push(i % group.pool.length);
    }

    if (m === 0) {
      for (let i = 0; i < group.legacyCount; i++) {
        const idx = month0Indices[i];
        add(idx, `catalog-${quarter}-${group.id}-${i}`);
      }
      for (let i = group.legacyCount; i < group.count; i++) {
        const idx = month0Indices[i];
        add(idx, `catalog-v2-${quarter}-${group.id}-${idx}`);
      }
    } else {
      // Remaining indices of the pool not used in month 0 to ensure zero repeats within a single year:
      const remaining = [];
      for (let i = 0; i < group.pool.length; i++) {
        if (!month0Indices.includes(i)) remaining.push(i);
      }
      const start = (m - 1) * group.count;
      for (let i = 0; i < group.count; i++) {
        const idx = remaining[(start + i) % remaining.length];
        add(idx, `catalog-v2-${quarter}-${group.id}-${idx}`);
      }
    }
    return offers;
  });
  return [...VIU_ORIGINALS, ...rotation];
}

// Each 30-day broadcast month gets its own rotating offers. Keep permanent
// ViuTV catalogue IDs stable so earlier purchases and saved rights remain valid.
export function catalogForMonth(day) {
  const month=marketMonthForDay(day);
  return catalogForQuarter(month).map(item=>item.id.startsWith('viu-original-')?item:{
    ...item,
    id:month===0?item.id:`market-${month}-${item.id}`,
    marketMonth:month
  });
}

const rivalPremierePools={
  jade:[['刑偵日記 II','刑偵劇',84],['豪門風雲錄','商戰劇',85],['白色強人 3','律政醫療',86],['金宵怪談新篇','奇幻懸疑',83],['巾幗梟雄風雲','年代史詩',87],['宮心計之深宮鬥','宮廷權謀',84]],
  viu:[['男排熱血新章','青春運動',76],['二月廿九之約','奇幻愛情',79],['大叔甜蜜愛火','都市喜劇',81],['繩角格鬥王','熱血拳擊',77],['季前熱血單挑','偶像籃球',78],['瑪嘉烈與大衛新篇','都會愛情',76]],
  hoy:[['星級廚神爭霸','飲食綜藝',70],['空間大改造香港版','家居裝修',72],['美味好煮意','生活美食',69],['再見枕邊人外購篇','外購愛情',73],['老友生活誌','健康長壽',68],['香港秘境遊','本土旅遊',71]],
  city:[['刑偵日記 II','刑偵劇',84],['豪門風雲錄','商戰劇',85],['白色強人 3','律政醫療',86],['金宵怪談新篇','奇幻懸疑',83],['巾幗梟雄風雲','年代史詩',87],['宮心計之深宮鬥','宮廷權謀',84]],
  local:[['男排熱血新章','青春運動',76],['二月廿九之約','奇幻愛情',79],['大叔甜蜜愛火','都市喜劇',81],['繩角格鬥王','熱血拳擊',77],['季前熱血單挑','偶像籃球',78],['瑪嘉烈與大衛新篇','都會愛情',76]]
};
export function rivalPremiere(rival,day) {
  const month=marketMonthForDay(day),pool=rivalPremierePools[rival.id]??rivalPremierePools.jade;
  let entry;
  if (rival.id==='viu'||rival.id==='local') {
    // Phase B4: ViuTV (話題王) premieres skew toward high-buzz kinds
    // (youth / idol / romance / comedy / sports heat), rotating the top three.
    const buzzWords=['青春','偶像','愛情','喜劇','熱血','運動'];
    const scored=pool.map((item,index)=>({item,index,score:item[2]+(buzzWords.some(word=>item[1].includes(word))?6:0)}))
      .sort((a,b)=>b.score-a.score||a.index-b.index);
    entry=scored[month%Math.min(3,scored.length)].item;
  } else {
    entry=pool[month%pool.length];
  }
  const [title,genre,baseRating]=entry;
  // Phase B4: HOY TV (量產王) premieres rate slightly lower.
  const rating=rival.id==='hoy'?baseRating-3:baseRating;
  return {title,genre,rating,month,slot:'19:00–21:00'};
}

