export function isEuropeanFootballSummerBreak(day = 1) {
  const monthInYear = (marketMonthForDay(day) % 12) + 1;
  return monthInYear === 7 || monthInYear === 8;
}

export function isUclMatchWeek(day = 1) {
  if (isEuropeanFootballSummerBreak(day)) return false;
  const weekNum = Math.floor((day - 1) / 7) + 1;
  return weekNum % 2 === 0;
}

export function isPlPausedWeek(day = 1) {
  if (isEuropeanFootballSummerBreak(day)) return true;
  return isUclMatchWeek(day);
}

export function getSportsConfig(event) {
  if (!event) return null;
  const name = event.name || '';
  const sport = event.sport || '';
  const id = event.id || '';

  if (sport === '賽馬直播' || name.includes('賽馬') || id.startsWith('racing-')) {
    return {
      type: 'racing',
      name: '香港賽馬現場直播',
      icon: '🏇',
      // Real-world HK Horse Racing broadcast windows:
      // Wednesday night: 7pm to 11pm (19:00 - 23:00 HK time) -> Happy Valley 跑馬地夜馬
      // Sunday afternoon: 1pm to 6pm (13:00 - 18:00 HK time) -> Sha Tin 沙田日馬
      // Season: September to June (all months exclude July & August 7月、8月暑期休季)
      matchDays: [2, 6], // Wed (2), Sun (6)
      wednesdayDays: [2],
      sundayDays: [6],
      defaultSlots: [
        { days: [2], start: 19, duration: 4, label: '跑馬地夜馬直播（週三 19:00–23:00）' },
        { days: [6], start: 13, duration: 5, label: '沙田日馬直播（週日 13:00–18:00）' }
      ],
      isLiveHour: (day, hour) => {
        const monthInYear = (marketMonthForDay(day) % 12) + 1;
        if (monthInYear === 7 || monthInYear === 8) return false; // 7月、8月暑期休季
        const wd = weekdayForDay(day);
        if (wd === 2 && hour >= 19 && hour <= 22) return true; // 週三夜馬 19:00-23:00
        if (wd === 6 && hour >= 13 && hour <= 17) return true; // 週日日馬 13:00-18:00
        return false;
      },
      matchdaysInMonth: 8,
      isSummerBreak: (day) => {
        const monthInYear = (marketMonthForDay(day) % 12) + 1;
        return monthInYear === 7 || monthInYear === 8;
      },
      autoScheduleDesc: '已預排【跑馬地夜馬（週三 19:00–23:00）】及【沙田日馬（週日 13:00–18:00）】直播時段（7、8月暑期休季停跑）。收視不追求爆發性超高，但基本盤極其穩定！'
    };
  }

  if (sport === '英超聯賽' || name.includes('英格蘭超級聯賽') || name.includes('英超') || id.startsWith('pl-')) {
    return {
      type: 'pl',
      name: '英超聯賽',
      icon: '⚽',
      // Real-world Asian/HK broadcast windows:
      // Strictly weekend only: Sat & Sun (19:00 - 24:00 HK time)
      // Never overlaps with Champions League (Tue & Wed 01:00 - 05:00 midnight)
      // When Champions League has matches during the week, Premier League pauses that week!
      matchDays: [5, 6], // Sat, Sun only
      weekendDays: [5, 6],     // Sat, Sun
      midweekDays: [],
      defaultSlots: [
        { days: [5, 6], start: 19, duration: 5, label: '週末焦點賽事（週六、日 19:00–24:00）' }
      ],
      isLiveHour: (day, hour) => {
        if (isEuropeanFootballSummerBreak(day)) return false;
        if (isPlPausedWeek(day)) return false; // 歐聯比賽週，英超全週休戰暫停
        const wd = weekdayForDay(day);
        return (wd === 5 || wd === 6) && (hour >= 19 && hour <= 23);
      },
      isSummerBreak: isEuropeanFootballSummerBreak,
      matchdaysInMonth: 4,
      autoScheduleDesc: '已預排【週末焦點（週六日 19:00–24:00）】直播時段。時段與歐聯完全分開，絕不重疊；逢歐聯比賽週英超休戰暫停；7、8月暑期休季。'
    };
  }

  if (sport === '歐聯賽事' || name.includes('歐洲聯賽冠軍盃') || name.includes('歐聯') || id.startsWith('ucl-')) {
    return {
      type: 'ucl',
      name: '歐聯賽事',
      icon: '⭐',
      // Real-world Asian/HK broadcast windows:
      // Midweek ONLY: Tue & Wed (01:00 - 05:00 midnight)
      // UCL NEVER plays on Sat/Sun weekends or Mon/Thu/Fri!
      matchDays: [1, 2],       // Tue, Wed
      midweekDays: [1, 2],     // Tue, Wed
      weekendDays: [],
      defaultSlots: [
        { days: [1, 2], start: 1, duration: 4, label: '歐聯淘汰賽深夜大戰（週二、三 01:00–05:00）' }
      ],
      isLiveHour: (day, hour) => {
        if (isEuropeanFootballSummerBreak(day)) return false;
        if (!isUclMatchWeek(day)) return false; // 僅於歐聯比賽週開戰
        const wd = weekdayForDay(day);
        return (wd === 1 || wd === 2) && (hour >= 1 && hour <= 4);
      },
      isSummerBreak: isEuropeanFootballSummerBreak,
      matchdaysInMonth: 4,
      autoScheduleDesc: '已預排【歐聯週中深夜大戰（週二、三 01:00–05:00）】直播時段（隔週歐聯比賽週進行；時段與英超週末完全獨立，絕不重疊；7、8月暑期休季）。'
    };
  }

  if (sport === '歐洲國家盃' || name.includes('歐洲國家盃') || id.startsWith('euro-')) {
    return {
      type: 'euro',
      name: '歐洲國家盃',
      icon: '🏆',
      matchDays: EVERY_DAY,
      defaultSlots: [
        { days: EVERY_DAY, start: 20, duration: 6, label: '歐國盃賽事直播（每日 20:00–02:00）' }
      ],
      isLiveHour: (day, hour) => hour >= 20 || hour <= 2,
      matchdaysInMonth: 30,
      autoScheduleDesc: '已預排每日 20:00–02:00 歐洲國家盃賽事直播！'
    };
  }

  if (sport === 'FIFA世界盃' || name.includes('世界盃') || id.startsWith('football-')) {
    return {
      type: 'worldcup',
      name: 'FIFA世界盃',
      icon: '🌍',
      matchDays: EVERY_DAY,
      defaultSlots: [
        { days: EVERY_DAY, start: 19, duration: 6, label: '世界盃狂熱直播（每日 19:00–01:00）' }
      ],
      isLiveHour: (day, hour) => hour >= 18 || hour <= 2,
      matchdaysInMonth: 30,
      autoScheduleDesc: '已預排每日 19:00–01:00 世界盃狂熱直播時段！'
    };
  }

  if (sport === '夏季奧運' || sport === '冬季奧運' || name.includes('奧運') || id.startsWith('games-') || id.startsWith('winter-')) {
    return {
      type: 'olympics',
      name: '奧林匹克運動會',
      icon: '🏅',
      matchDays: EVERY_DAY,
      defaultSlots: [
        { days: EVERY_DAY, start: 15, duration: 8, label: '奧運全日直擊（每日 15:00–23:00）' }
      ],
      isLiveHour: (day, hour) => hour >= 15 && hour <= 23,
      matchdaysInMonth: 30,
      autoScheduleDesc: '已預排每日 15:00–23:00 奧運焦點賽事直播！'
    };
  }

  if (sport === '排球及欖球' || id.startsWith('vnl-')) {
    return {
      type: 'weekend_tourney',
      name: '國際排球及欖球',
      icon: '🏐',
      matchDays: [4, 5, 6],
      defaultSlots: [
        { days: [4, 5, 6], start: 14, duration: 6, label: '巡迴賽直播（週五至日 14:00–20:00）' }
      ],
      isLiveHour: (day, hour) => {
        const wd = weekdayForDay(day);
        return [4, 5, 6].includes(wd) && hour >= 14 && hour <= 20;
      },
      matchdaysInMonth: 12,
      autoScheduleDesc: '已預排週五至日 14:00–20:00 賽事直播！'
    };
  }

  if (sport === '網球及賽車' || id.startsWith('f1-')) {
    return {
      type: 'f1_tennis',
      name: '溫網及F1大獎賽',
      icon: '🏎️',
      matchDays: [5, 6],
      defaultSlots: [
        { days: [5, 6], start: 19, duration: 5, label: '週末焦點決賽（週六、日 19:00–24:00）' }
      ],
      isLiveHour: (day, hour) => {
        const wd = weekdayForDay(day);
        return (wd === 5 || wd === 6) && hour >= 19 && hour <= 23;
      },
      matchdaysInMonth: 8,
      autoScheduleDesc: '已預排週六、日 19:00–24:00 焦點決賽直播！'
    };
  }

  return {
    type: 'generic_sports',
    name: event.name,
    icon: event.icon || '🏅',
    matchDays: EVERY_DAY,
    defaultSlots: [
      { days: EVERY_DAY, start: 18, duration: 6, label: '焦點賽事直播（每日 18:00–24:00）' }
    ],
    isLiveHour: (day, hour) => (hour >= 18 && hour <= 23) || (hour >= 1 && hour <= 4),
    matchdaysInMonth: 30,
    autoScheduleDesc: '已預排賽事直播時段！'
  };
}

export function sportsDurationDays(event) {
  if (!event) return DAYS_PER_QUARTER;
  const cfg = getSportsConfig(event);
  // Only genuine full-season packages run for a full year (360 days). A
  // knockout-only package (e.g. ucl-2028 歐聯淘汰賽與決賽） lasts one quarter.
  const isFullSeason = cfg?.type === 'pl' || cfg?.type === 'racing' || (cfg?.type === 'ucl' && (event.name ?? '').includes('全季'));
  return isFullSeason ? DAYS_PER_QUARTER * 4 : DAYS_PER_QUARTER;
}

export function isSportsActive(event, state) {
  if (!event || !event.resolved || event.winner !== '你的電視台') return false;
  const wonDay = event.wonDay ?? Math.max(1, (event.wonQuarter ?? (event.quarter - 1)) * DAYS_PER_QUARTER + 1);
  return state.day >= wonDay && state.day < wonDay + sportsDurationDays(event);
}

export function getActiveSportsEvents(state) {
  return (state.events ?? []).filter(e => isSportsActive(e, state));
}

export function activeBiddingEvents(state) {
  return (state.events ?? []).filter(e => !e.resolved && e.quarter >= state.quarter && e.quarter - state.quarter <= 3);
}

export function currentEvent(state) {
  const list = activeBiddingEvents(state);
  return list[0] ?? null;
}

function ensureEvents(state) {
  for (const ev of SPORTS_CALENDAR) {
    if (!state.events.some(e => e.id === ev.id)) state.events.push(new BiddingEvent(ev));
  }
  // Beyond quarter 26, dynamically append recurring premier tournaments every 4 years
  const last = state.events.at(-1);
  if (last && state.quarter >= last.quarter - 2) {
    const q = last.quarter + 4;
    const year = 2028 + Math.floor(q / 4);
    const isPl = q % 4 === 1;
    const isUcl = q % 4 === 3;
    const isWc = q % 16 === 10;
    const isEuro = q % 16 === 14;
    const name = isPl ? `${year}/${String(year+1).slice(2)} 英格蘭超級聯賽（全季轉播權）`
      : isUcl ? `${year}/${String(year+1).slice(2)} 歐洲聯賽冠軍盃（歐聯全季）`
      : isWc ? `${year} FIFA 世界盃足球賽`
      : isEuro ? `${year} 歐洲國家盃（UEFA Euro）`
      : `${year} 國際大型綜合體育盛會`;
    const id = `sports-${year}-${q}`;
    state.events.push(new BiddingEvent({ id, name, quarter: q, floor: last.floor + 500_000, adTarget: last.adTarget + 600_000 }));
  }
}

