export function isToolActive(state, toolId) {
  if (!state?.activeTools?.length) return false;
  return state.activeTools.some(t => t.id === toolId && t.expiresDay > state.day);
}

export function getToolTimeRemaining(state, toolId) {
  const tool = (state.activeTools ?? []).find(t => t.id === toolId && t.expiresDay > state.day);
  return tool ? Math.max(0, tool.expiresDay - state.day) : 0;
}

export function buyShopTool(state, toolId) {
  const tool = SHOP_TOOLS.find(t => t.id === toolId);
  if (!tool) throw Error('找不到該項道具。');
  if (state.cash < tool.price) throw Error(`資金不足！需要 ${money(tool.price)}。`);
  state.cash -= tool.price;
  state.activeTools ??= [];
  const existing = state.activeTools.find(t => t.id === toolId);
  if (existing && existing.expiresDay > state.day) {
    existing.expiresDay += tool.durationDays;
    existing.price = tool.price;
    note(state, `【道具續期】${tool.name} 租期已延長 30 日（至第 ${existing.expiresDay} 日）！`, 'good');
    return existing;
  } else {
    const record = {
      id: tool.id,
      name: tool.name,
      icon: tool.icon,
      price: tool.price,
      boughtDay: state.day,
      expiresDay: state.day + tool.durationDays,
      effectBadge: tool.effectBadge
    };
    if (existing) {
      existing.boughtDay = state.day;
      existing.expiresDay = record.expiresDay;
      existing.price = tool.price;
    } else {
      state.activeTools.push(record);
    }
    note(state, `【道具購入】成功購入「${tool.name}」（有效 30 日，至第 ${record.expiresDay} 日）！`, 'good');
    return record;
  }
}

export const ARTIST_CONTRACT_DAYS = 360; // 1 year = 360 game days

export function getStationName(stationId) {
  if (stationId === 'player') return '你的電視台';
  if (stationId === 'jade' || stationId === 'city') return '翡翠台';
  if (stationId === 'viu' || stationId === 'local') return 'ViuTV';
  if (stationId === 'hoy') return 'HOY TV';
  return '自由身';
}

export function initTalentContracts(state) {
  state.talent ??= {};
  state.lastAiredDays ??= {};
  const playerInitial = new Set(['edaan', 'anson_lo', 'wong_tak_bun']);
  const jadeInitial = new Set(['kenneth', 'moses', 'samantha', 'hera', 'vincent', 'shaun']);
  const viuInitial = new Set(['lokman', 'an_ck', 'kaki_sham', 'hanna_chan', 'ling_man_lung', 'tiger_yau']);
  const hoyInitial = new Set(['lawrence', 'kan_mo_wah', 'lam', 'chi']);

  for (const actor of ACTORS) {
    const station = playerInitial.has(actor.id) ? 'player'
      : jadeInitial.has(actor.id) ? 'jade'
      : viuInitial.has(actor.id) ? 'viu'
      : hoyInitial.has(actor.id) ? 'hoy'
      : 'free';
    state.talent[actor.id] = {
      skill: actor.skill,
      fame: actor.skill - 10,
      fee: actor.fee,
      stamina: 100,
      contractType: 'freelance',
      contractDaysLeft: 0,
      trainedCount: 0,
      station,
      contractExpiresDay: station === 'free' ? null : 360
    };
    state.lastAiredDays[actor.id] = 1;
  }
}

export function artistSignCost(talent, actor) {
  return Math.round(((talent?.fee ?? actor?.fee ?? 500_000) * 1.5) / 10_000) * 10_000;
}

export function artistRenewCost(talent, actor) {
  return Math.round(((talent?.fee ?? actor?.fee ?? 500_000) * 1.2) / 10_000) * 10_000;
}

export function signArtist(state, actorId, station = 'player') {
  const actor = ACTORS.find(a => a.id === actorId);
  if (!actor) throw Error('找不到該位演員。');
  state.talent ??= {};
  state.talent[actorId] ??= { fame: actor.skill - 10, fee: actor.fee, station: 'free', contractExpiresDay: null };
  const talent = state.talent[actorId];

  if (talent.station !== 'free' && Number.isInteger(talent.contractExpiresDay) && talent.contractExpiresDay > state.day) {
    if (talent.station === station) throw Error(`【${actor.name}】已是旗下簽約藝人，如欲延期請點擊「續約」。`);
    throw Error(`【${actor.name}】目前受聘於${getStationName(talent.station)}（合約尚餘 ${talent.contractExpiresDay - state.day} 日），無法簽約！`);
  }

  const cost = artistSignCost(talent, actor);
  if (station === 'player') {
    if (state.cash < cost) throw Error(`資金不足！簽下【${actor.name}】1 年合約需要 ${money(cost)}。`);
    state.cash -= cost;
  }
  talent.station = station;
  talent.contractExpiresDay = state.day + ARTIST_CONTRACT_DAYS;
  talent.renewPromptSent = false;
  if (station === 'player') {
    note(state, `【藝人簽約】成功與【${actor.name}】簽下 1 年獨家藝人合約（簽約金 ${money(cost)}，合約期至第 ${talent.contractExpiresDay} 日）！`, 'good');
    markChallenge(state, 'first-signing');
  }
  return talent;
}

export function renewArtistContract(state, actorId, charge = true) {
  const actor = ACTORS.find(a => a.id === actorId);
  if (!actor) throw Error('找不到該位演員。');
  state.talent ??= {};
  const talent = state.talent[actorId];
  if (!talent || talent.station !== 'player') throw Error(`【${actor.name}】不是我台旗下簽約藝人，無法續約。`);

  const cost = artistRenewCost(talent, actor);
  if (charge) {
    if (state.cash < cost) throw Error(`資金不足！為【${actor.name}】續約 1 年需要 ${money(cost)}。`);
    state.cash -= cost;
  }
  const baseDay = (Number.isInteger(talent.contractExpiresDay) && talent.contractExpiresDay > state.day) ? talent.contractExpiresDay : state.day;
  talent.contractExpiresDay = baseDay + ARTIST_CONTRACT_DAYS;
  talent.station = 'player';
  talent.renewPromptSent = false;
  note(state, `【合約續期】成功與【${actor.name}】續約 1 年（合約期延長至第 ${talent.contractExpiresDay} 日${charge ? `，花費 ${money(cost)}` : ''}）！`, 'good');
  return talent;
}

export function checkCompetitorArtistSignings(state, rng = Math.random) {
  state.talent ??= {};
  const freeActors = ACTORS.filter(a => (state.talent[a.id]?.station ?? 'free') === 'free');
  if (!freeActors.length) return;

  const rivals = state.rivals ?? [{ id: 'jade', name: '翡翠台' }, { id: 'viu', name: 'ViuTV' }, { id: 'hoy', name: 'HOY TV' }];
  // Phase B4: 翡翠台 (挖角王) prefers artists the player has cast recently.
  const recentCastIds = new Set();
  for (const program of state.library ?? []) {
    if ((program.lastAiredDay ?? 0) >= state.day - 45) {
      for (const id of program.castIds ?? []) recentCastIds.add(id);
    }
  }
  for (const rival of rivals) {
    const isPoacher = rival.id === 'jade' || rival.id === 'city';
    if (rng() < (isPoacher ? 0.65 : 0.50)) {
      let pool = freeActors.filter(a => (state.talent[a.id]?.station ?? 'free') === 'free');
      if (!pool.length) break;
      if (isPoacher) {
        const targets = pool.filter(a => recentCastIds.has(a.id));
        if (targets.length) pool = targets;
      }
      const pick = pool[Math.floor(rng() * pool.length)];
      if (pick) {
        state.talent[pick.id].station = rival.id;
        state.talent[pick.id].contractExpiresDay = state.day + ARTIST_CONTRACT_DAYS;
        note(state, `【藝人轉會動態】${rival.name} 宣佈簽下自由身藝人【${pick.name}】1 年獨家合約！`, 'neutral');
      }
    }
  }
}

export function refreshMarketRivalBuys(state, rng = Math.random) {
  state.rivalPurchases ??= [];
  state.rivalPurchases = state.rivalPurchases.filter(r => r.expiresDay > state.day);
  const currentMonth = marketMonthForDay(state.day);
  const activeThisMonth = state.rivalPurchases.filter(r => r.marketMonth === currentMonth);
  if (activeThisMonth.length >= 3) return state.rivalPurchases;

  const currentListings = catalogForMonth(state.day);
  const ownedTitles = new Set(state.library.map(p => p.title));
  const rivalOwnedTitles = new Set(state.rivalPurchases.map(r => r.title));

  const candidates = currentListings.filter(item =>
    !item.id.startsWith('viu-original-') &&
    ['korean', 'japanese', 'taiwan', 'western', 'chinese'].includes(item.group) &&
    !ownedTitles.has(item.title) &&
    !rivalOwnedTitles.has(item.title)
  );

  if (!candidates.length) return state.rivalPurchases;

  // 1. Jade TV (翡翠台 / city) buys 1 blockbuster
  const jadeExisting = state.rivalPurchases.find(r => (r.rivalId === 'jade' || r.rivalId === 'city') && r.marketMonth === currentMonth);
  if (!jadeExisting) {
    const jadeCandidates = [...candidates].sort((a, b) => (b.rating + b.buzz) - (a.rating + a.buzz));
    const jadePick = jadeCandidates[0];
    if (jadePick) {
      const buyRecord = {
        id: `rival-buy-${state.day}-${jadePick.id}`,
        marketItemId: jadePick.id,
        marketMonth: currentMonth,
        title: jadePick.title,
        rivalId: 'jade',
        rivalName: '翡翠台',
        origin: jadePick.origin || '外購',
        category: jadePick.category,
        rating: jadePick.rating,
        cost: jadePick.cost,
        startDay: state.day,
        expiresDay: (currentMonth + 1) * DAYS_PER_MARKET_MONTH + 1
      };
      state.rivalPurchases.push(buyRecord);
      rivalOwnedTitles.add(jadePick.title);
      note(state, `【對手動向】翡翠台豪擲 ${money(jadePick.cost)} 搶購${jadePick.origin}話題作《${jadePick.title}》獨家播映權！`, 'neutral');
    }
  }

  // 2. ViuTV (viu / local) buys 1 trendy/youth/mystery title
  const viuExisting = state.rivalPurchases.find(r => (r.rivalId === 'viu' || r.rivalId === 'local') && r.marketMonth === currentMonth);
  if (!viuExisting) {
    const viuCandidates = candidates.filter(c => !rivalOwnedTitles.has(c.title));
    const preferred = viuCandidates.filter(c => ['日本', '韓國'].includes(c.origin));
    const pool = preferred.length ? preferred : viuCandidates;
    const viuPick = pool[Math.floor(rng() * pool.length)];
    if (viuPick) {
      const buyRecord = {
        id: `rival-buy-${state.day}-${viuPick.id}`,
        marketItemId: viuPick.id,
        marketMonth: currentMonth,
        title: viuPick.title,
        rivalId: 'viu',
        rivalName: 'ViuTV',
        origin: viuPick.origin || '外購',
        category: viuPick.category,
        rating: viuPick.rating,
        cost: viuPick.cost,
        startDay: state.day,
        expiresDay: (currentMonth + 1) * DAYS_PER_MARKET_MONTH + 1
      };
      state.rivalPurchases.push(buyRecord);
      rivalOwnedTitles.add(viuPick.title);
      note(state, `【對手動向】ViuTV 以 ${money(viuPick.cost)} 買入${viuPick.origin}潮流作《${viuPick.title}》播映權！`, 'neutral');
    }
  }

  // 3. HOY TV (hoy) buys 1 lifestyle/comfort drama
  const hoyExisting = state.rivalPurchases.find(r => r.rivalId === 'hoy' && r.marketMonth === currentMonth);
  if (!hoyExisting) {
    const hoyCandidates = candidates.filter(c => !rivalOwnedTitles.has(c.title));
    const preferred = hoyCandidates.filter(c => ['台灣', '日本', '內地'].includes(c.origin));
    const pool = preferred.length ? preferred : hoyCandidates;
    const hoyPick = pool[Math.floor(rng() * pool.length)];
    if (hoyPick) {
      const buyRecord = {
        id: `rival-buy-${state.day}-${hoyPick.id}`,
        marketItemId: hoyPick.id,
        marketMonth: currentMonth,
        title: hoyPick.title,
        rivalId: 'hoy',
        rivalName: 'HOY TV',
        origin: hoyPick.origin || '外購',
        category: hoyPick.category,
        rating: hoyPick.rating,
        cost: hoyPick.cost,
        startDay: state.day,
        expiresDay: (currentMonth + 1) * DAYS_PER_MARKET_MONTH + 1
      };
      state.rivalPurchases.push(buyRecord);
      note(state, `【對手動向】HOY TV 以 ${money(hoyPick.cost)} 買入${hoyPick.origin}精選作《${hoyPick.title}》播映權！`, 'neutral');
    }
  }

  return state.rivalPurchases;
}

export function newGame() {
  const state = new StationState();
  initTalentContracts(state);
  state.activeTools = [];
  state.adContractsMarket = AD_CONTRACT_TEMPLATES.map(t => ({ ...t, daysElapsed: 0, ratings: [] }));
  ensureEvents(state);
  ensureChallenges(state);
  refreshMarketRivalBuys(state, () => 0.5);
  return state;
}

export function productionQuote(state,{kind='drama',actorIds=[],budgetId='standard',episodeHours=2,episodeCount=8,styleId='mainstream',hookId='none'}) {
  const format=CONTENT_TYPES.find(item=>item.id===kind),budget=BUDGETS.find(item=>item.id===budgetId),style=PRODUCTION_STYLES.find(item=>item.id===styleId),hook=PRODUCTION_HOOKS.find(item=>item.id===hookId);
  if (!format||!budget||!style||!hook||!Number.isInteger(episodeHours)||episodeHours<1||episodeHours>4||!isDailyFormat(kind)&&!isOneOffEvent(kind)&&(!Number.isInteger(episodeCount)||!EPISODE_COUNTS.includes(episodeCount))) throw Error('請選擇有效嘅每集時長、集數、製作預算同拍攝方向。');
  const cast=kind==='drama'?actorIds.map(id=>ACTORS.find(actor=>actor.id===id)):[];
  if (cast.some(actor=>!actor)||new Set(actorIds).size!==actorIds.length) throw Error('演員名單有誤。');
  let perEpisode=Math.round(budget.cost*(kind==='drama'?1:format.factor)*(1+(episodeHours-1)*.45)*style.factor/1_000)*1_000;
  if (isToolActive(state, 'script_workshop')) perEpisode = Math.round(perEpisode * 0.90);
  const fees=cast.reduce((sum,actor)=>{
    const t = state.talent[actor.id];
    if (t?.contractType === 'exclusive' && (t?.contractDaysLeft ?? 0) > 0) return sum;
    const isOurContract = t?.station === 'player' && t?.contractExpiresDay > state.day;
    const effectiveFee = isOurContract ? Math.round(actor.fee * 0.6) : (t?.fee ?? actor.fee);
    return sum + effectiveFee;
  }, 0);
  const episodes=isDailyFormat(kind)?0:isOneOffEvent(kind)?1:episodeCount;
  return {perEpisode,episodes,fees,total:perEpisode*(episodes||1)+fees+hook.cost,style,budget,cast,hook};
}

export function rivalAtHour(state,rival,hour,day=state.day) {
  const block=rival.schedule.find(item=>hoursInBlock(item).includes(hour));
  if (!block) return null;
  // Phase B4: premieres normally sit at 19:00-20:00; a rival with a serious
  // grudge instead targets the player's strongest daypart.
  let premiere=premiereWindowHours(state,rival).includes(hour)?rivalPremiere(rival,day):null;
  const deal=hour>=21&&hour<23?(state.distributionDeals??[]).find(item=>item.rivalId===rival.id&&item.startDay<=day&&day<item.expiresDay):null;
  const rivalMarketBuy=hour>=21&&hour<23&&!deal?(state.rivalPurchases??[]).find(item=>item.rivalId===rival.id&&item.startDay<=day&&day<item.expiresDay):null;
  // Phase B4: HOY TV (量產王) runs a second, cheaper premiere at 21:00-22:00
  // whenever a distribution deal or market buy has not taken the slot.
  if (!premiere && rival.id==='hoy' && hour>=21 && hour<23 && !deal && !rivalMarketBuy) {
    const altPool=rivalPremierePools.hoy,alt=altPool[(marketMonthForDay(day)+3)%altPool.length];
    premiere={title:alt[0],genre:alt[1],rating:alt[2]-9,month:marketMonthForDay(day),slot:'21:00–23:00'};
  }
  const title=deal?.title??rivalMarketBuy?.title??premiere?.title??block.rotation?.[state.quarter%block.rotation.length]??block.title;
  const wave=(day*11+hour*3+(rival.id==='jade'||rival.id==='city'?0:rival.id==='viu'||rival.id==='local'?2:4))%7-3;
  const base=deal?.rating??(rivalMarketBuy?rivalMarketBuy.rating+2:null)??premiere?.rating??block.rating;
  let eventMod = 0;
  if (state.breakingEvent) {
    if (state.breakingEvent.ratingMods?.all) eventMod += Math.round(state.breakingEvent.ratingMods.all * 0.5);
    if ((hour === 17 || hour === 18) && state.breakingEvent.ratingMods?.kinds?.news) eventMod += Math.round(state.breakingEvent.ratingMods.kinds.news * 0.5);
    if (hour >= 9 && hour <= 10 && state.breakingEvent.ratingMods?.kinds?.finance) eventMod += Math.round(state.breakingEvent.ratingMods.kinds.finance * 0.5);
  }
  // Phase B4: ViuTV (話題王) carries a small buzz bonus in evening slots.
  const personalityMod=(rival.id==='viu'||rival.id==='local')&&hour>=19&&hour<=22?2:0;
  return {title,rating:clamp(base+wave+Math.min(state.quarter%3,2)+eventMod+personalityMod,1,98),block,rivalMarketBuy,deal,premiere,category:block.category,desc:block.desc};
}

export function distributionQuote(program,exclusive=false) {
  if(!program || program.id.startsWith('start-') || program.kind==='catalog') throw Error('只有你親自拍攝嘅作品先可以賣埠。');
  if(isDailyFormat(program.kind) && !program.episodes) throw Error('每日新聞同財經係持續製作，冇完整劇集可以賣埠。');
  if(program.soldExclusive) throw Error('呢套節目已經獨家賣斷。');
  const value=(program.episodes||12)*55_000+program.quality*7_000+program.buzz*3_000;
  return Math.round(value*(exclusive?1.35:.55)/10_000)*10_000;
}
export function sellProduction(state,programId,rivalId,exclusive=false) {
  const program=state.library.find(item=>item.id===programId);
  const rival=state.rivals.find(item=>item.id===rivalId);
  if(!rival) throw Error('請揀有效嘅買家電視台。');
  const amount=distributionQuote(program,exclusive);
  state.distributionDeals??=[];
  if(state.distributionDeals.some(item=>item.programId===programId && item.rivalId===rivalId)) throw Error('呢間台已經買咗呢套節目，不能重複賣。');
  if(exclusive && state.distributionDeals.some(item=>item.programId===programId)) throw Error('節目已有其他台播映授權，不能再獨家賣斷。');
  const deal={programId,title:program.title,rivalId,startDay:state.day,expiresDay:state.day+30,exclusive,amount,rating:clamp(program.rating+4,1,98)};
  state.distributionDeals.push(deal);
  state.cash+=amount;
  if(exclusive){program.soldExclusive=true;state.schedule=state.schedule.filter(item=>item.programId!==programId);}
  note(state,`《${program.title}》${exclusive?'獨家賣斷':'聯播授權'}畀${rival.name}，收取 ${money(amount)}；對方未來 30 日晚間播出。`,'good');
  markChallenge(state, 'first-sale');
  return deal;
}

function note(state,text,type='neutral') {
  state.log.unshift({quarter:state.quarter,text,type});
  state.log = state.log.slice(0,16);
}

// ---------------------------------------------------------------------------
// Phase B1: 挑戰任務 (Challenge missions)
// Progress is evaluated at the end of advanceDay. Event-based challenges are
// recorded as markers (state.challengeFlags) by the relevant action functions
// so those actions never change cash themselves; rewards are queued on
// completion and paid automatically at the start of the next broadcast day,
// which keeps a single day's cash accounting (daily.net) exact.
// ---------------------------------------------------------------------------
export const CHALLENGES = [
  { id:'prime-first', tier:'新手', title:'贏得第一個黃金時段', desc:'在 18:00 至 22:00 黃金時段內，任何一個小時收視贏過全部對台。', target:1, reward:{cash:200_000}, rewardText:'獎勵 $200k' },
  { id:'win-five-hours', tier:'新手', title:'一日贏 5 個小時', desc:'單日贏出 5 個或以上小時時段（進度記錄最佳單日成績）。', target:5, reward:{cash:300_000}, rewardText:'獎勵 $300k' },
  { id:'first-production', tier:'新手', title:'完成第一套自製劇', desc:'完成一套自家製作節目（即製節目或製作工程均可）。', target:1, reward:{cash:300_000}, rewardText:'獎勵 $300k' },
  { id:'first-signing', tier:'新手', title:'簽第一位藝人', desc:'與任何一位藝人簽下藝人合約。', target:1, reward:{cash:200_000}, rewardText:'獎勵 $200k' },
  { id:'prime-streak-3', tier:'進階', title:'連續 3 日贏 20:00 時段', desc:'連續 3 日在 20:00 時段收視贏過全部對台（中斷會重新計算）。', target:3, reward:{cash:600_000}, rewardText:'獎勵 $600k' },
  { id:'monthly-champion', tier:'進階', title:'贏一次月度收視冠軍', desc:'在月度收視榜以我台節目奪得全港最高收視總冠軍。', target:1, reward:{cash:800_000, reputation:2}, rewardText:'獎勵 $800k · 口碑 +2' },
  { id:'sports-rights', tier:'進階', title:'贏得一項體育版權', desc:'透過競投或一口價買斷贏得一項體育轉播權。', target:1, reward:{cash:800_000}, rewardText:'獎勵 $800k' },
  { id:'first-sale', tier:'進階', title:'賣出一套自製節目', desc:'將一套自製節目聯播授權或獨家賣斷畀對台。', target:1, reward:{cash:600_000}, rewardText:'獎勵 $600k' },
  { id:'annual-award', tier:'長遠', title:'贏年度大獎', desc:'在年度頒獎禮贏得任何一項大獎。', target:1, reward:{cash:1_500_000, fans:3}, rewardText:'獎勵 $1.5m · 熱度 +3' },
  { id:'sub-channel', tier:'長遠', title:'開辦數碼二台', desc:'斥資開辦 24 小時數碼二台頻道。', target:1, reward:{cash:1_000_000}, rewardText:'獎勵 $1.0m' },
  { id:'cash-50m', tier:'長遠', title:'資金達到 $50m', desc:'電視台現金儲備達到 $50m（進度以百萬計）。', target:50, reward:{cash:2_000_000}, rewardText:'獎勵 $2.0m' }
];

export function ensureChallenges(state) {
  state.challenges ??= [];
  state.challengeFlags ??= {};
  state.pendingChallengeRewards ??= [];
  for (const def of CHALLENGES) {
    if (!state.challenges.some(entry => entry.id === def.id)) {
      state.challenges.push({ id: def.id, progress: 0, done: false });
    }
  }
  return state.challenges;
}

export function getChallengeList(state) {
  ensureChallenges(state);
  return CHALLENGES.map(def => {
    const entry = state.challenges.find(item => item.id === def.id);
    return { ...def, progress: entry?.progress ?? 0, done: entry?.done ?? false };
  });
}

// Records an event-based challenge as achieved; the reward itself is granted
// by the end-of-day evaluation, never synchronously inside an action.
export function markChallenge(state, id) {
  state.challengeFlags ??= {};
  state.challengeFlags[id] = true;
}

export function payChallengeRewards(state) {
  state.pendingChallengeRewards ??= [];
  if (!state.pendingChallengeRewards.length) return [];
  const paid = state.pendingChallengeRewards.splice(0, state.pendingChallengeRewards.length);
  for (const reward of paid) {
    if (reward.cash) state.cash += reward.cash;
    if (reward.reputation) state.reputation = clamp(state.reputation + reward.reputation, 0, 100);
    if (reward.fans) state.fans = clamp(state.fans + reward.fans, 0, 100);
    const parts = [
      reward.cash ? `獎金 ${money(reward.cash)}` : null,
      reward.reputation ? `口碑 +${reward.reputation}` : null,
      reward.fans ? `熱度 +${reward.fans}` : null
    ].filter(Boolean).join('、');
    note(state, `【挑戰達成】「${reward.title}」完成！${parts} 已入賬，繼續向其他挑戰進發。`, 'good');
  }
  return paid;
}

export function evaluateChallenges(state, daily) {
  ensureChallenges(state);
  const entries = Object.fromEntries(state.challenges.map(entry => [entry.id, entry]));
  const defOf = id => CHALLENGES.find(def => def.id === id);
  const setProgress = (id, value) => {
    const entry = entries[id];
    if (entry && !entry.done) entry.progress = clamp(Math.floor(value), 0, defOf(id).target);
  };
  const hours = daily?.hours ?? [];
  if (hours.some(h => h.hour >= 18 && h.hour <= 22 && h.rating > Math.max(...h.rivals))) setProgress('prime-first', 1);
  if (Number.isInteger(daily?.wins)) setProgress('win-five-hours', Math.max(entries['win-five-hours']?.progress ?? 0, daily.wins));
  const hour20 = hours.find(h => h.hour === 20);
  if (hour20 && entries['prime-streak-3'] && !entries['prime-streak-3'].done) {
    entries['prime-streak-3'].progress = hour20.rating > Math.max(...hour20.rivals)
      ? Math.min(3, (entries['prime-streak-3'].progress ?? 0) + 1)
      : 0;
  }
  if (state.challengeFlags['first-signing']) setProgress('first-signing', 1);
  if (state.challengeFlags['first-sale']) setProgress('first-sale', 1);
  if (state.challengeFlags['sports-rights']) setProgress('sports-rights', 1);
  if (state.challengeFlags['sub-channel']) setProgress('sub-channel', 1);
  if (state.challengeFlags['first-production'] || (state.productionProjects ?? []).some(p => p.status === 'completed' || p.status === 'delivered')) {
    setProgress('first-production', 1);
  }
  if (daily?.monthResult?.isOurWin) setProgress('monthly-champion', 1);
  if ((daily?.ceremony?.ourWins ?? 0) >= 1) setProgress('annual-award', 1);
  setProgress('cash-50m', Math.floor((state.cash ?? 0) / 1_000_000));
  const completed = [];
  for (const def of CHALLENGES) {
    const entry = entries[def.id];
    if (entry && !entry.done && entry.progress >= def.target) {
      entry.done = true;
      entry.progress = def.target;
      state.pendingChallengeRewards.push({ id: def.id, title: def.title, ...def.reward });
      completed.push(def.id);
    }
  }
  updateRivalGrudgeDaily(state, daily);
  return completed;
}

// ---------------------------------------------------------------------------
// Phase B4: 對手性格與恩怨 (Rival personalities + grudge)
// ---------------------------------------------------------------------------
