      calm: ['翡翠台最近忙住排佢哋嘅長壽劇，暫時未有針對你嘅動作。', '翡翠台高層心情唔錯，仲未將你放喺眼內。'],
      watch: ['翡翠台開始留意你台嘅排播，挖角名單據聞已經開咗個檔案。', '翡翠台對你近排嘅收視有啲眼紅，開會嗰陣提過你幾次。'],
